from pathlib import Path
p=Path('index.html')
s=p.read_text(encoding='utf-8')
old='''  <section id="view-reports" class="view"><div class="page-head"><div><div class="eyebrow">AUSWERTUNG</div><h1>Auswertungen</h1><p>Personal- und Besetzungskennzahlen im Überblick.</p></div></div><div class="stats" id="reportStats"></div></section>'''
new='''  <section id="view-reports" class="view"><div class="page-head"><div><div class="eyebrow">AUSWERTUNGEN</div><h1>Auswertungs-Dashboard</h1><p>Arbeitsstunden, Besetzung, Abwesenheiten und Auffälligkeiten auf einen Blick.</p></div><select id="reportPeriod" onchange="renderReports()"><option value="week">Diese Woche</option><option value="month">Dieser Monat</option></select></div><div class="stats" id="reportStats"></div><div class="panel-grid" style="margin-top:14px"><div class="card table-card"><div class="table-head"><h3>SOLL / IST Besetzung</h3></div><div id="reportCoverage"></div></div><div class="card table-card"><div class="table-head"><h3>Abwesenheiten</h3></div><div id="reportAbsences"></div></div></div><div class="panel-grid" style="margin-top:14px"><div class="card table-card"><div class="table-head"><h3>Arbeitsstunden & Auslastung</h3></div><div id="reportHours"></div></div><div class="card table-card"><div class="table-head"><h3>Schichtverteilung</h3></div><div id="reportMix"></div></div></div><div class="card table-card" style="margin-top:14px"><div class="table-head"><h3>Auffälligkeiten</h3><span class="badge" id="reportAlertCount">0</span></div><div id="reportAlerts"></div></div></section>'''
if old not in s:
    raise SystemExit('alte Reports-Sektion nicht gefunden')
s=s.replace(old,new,1)
fn=r'''function reportDates(){const mode=document.getElementById('reportPeriod')?.value||'week';if(mode==='week')return currentWeekDates().map(iso);const base=currentWeekDates()[0],y=base.getFullYear(),m=base.getMonth(),last=new Date(y,m+1,0).getDate();return Array.from({length:last},(_,i)=>iso(new Date(y,m,i+1)))}
function hoursForEmployeeDates(employeeId,dates){return assignments.filter(a=>a.employeeId===employeeId&&dates.includes(a.date)).reduce((sum,a)=>{const t=typeById(a.type),st=(a.start||t?.start||'00:00').split(':').map(Number),en=(a.end||t?.end||'00:00').split(':').map(Number);let mins=(en[0]*60+en[1])-(st[0]*60+st[1]);if(mins<0)mins+=1440;return sum+mins/60},0)}
function renderReports(){const stats=document.getElementById('reportStats');if(!stats)return;const dates=reportDates(),wa=assignments.filter(a=>dates.includes(a.date)),active=employees.filter(e=>e.status==='active'),total=dates.reduce((z,d)=>z+TYPES.reduce((q,t)=>q+getSoll(d,t.id),0),0),open=dates.reduce((z,d)=>z+TYPES.reduce((q,t)=>q+Math.max(0,getSoll(d,t.id)-assignmentsFor(d,t.id).length),0),0),filled=total-open,cov=total?Math.round(filled/total*100):100,abs=absences.filter(a=>dates.includes(a.date));const hours=wa.reduce((sum,a)=>{const t=typeById(a.type),st=(a.start||t?.start||'00:00').split(':').map(Number),en=(a.end||t?.end||'00:00').split(':').map(Number);let mins=(en[0]*60+en[1])-(st[0]*60+st[1]);if(mins<0)mins+=1440;return sum+mins/60},0);stats.innerHTML=`<div class="stat"><div class="stat-icon">◷</div><div><small>Geplante Arbeitsstunden</small><strong>${hours.toFixed(1)}</strong><em>Stunden im Zeitraum</em></div></div><div class="stat"><div class="stat-icon">◉</div><div><small>Besetzungsquote</small><strong>${cov}%</strong><em>${filled} von ${total} Positionen</em></div></div><div class="stat"><div class="stat-icon">△</div><div><small>Offene Positionen</small><strong>${open}</strong><em>${open?'Handlungsbedarf':'Vollständig besetzt'}</em></div></div><div class="stat"><div class="stat-icon">☼</div><div><small>Abwesenheiten</small><strong>${abs.length}</strong><em>${new Set(abs.map(a=>a.employeeId)).size} Mitarbeiter betroffen</em></div></div>`;const coverage=document.getElementById('reportCoverage');coverage.innerHTML=TYPES.map(t=>{const soll=dates.reduce((z,d)=>z+getSoll(d,t.id),0),ist=wa.filter(a=>a.type===t.id).length,p=soll?Math.round(ist/soll*100):100;return `<div class="section-box" style="margin-bottom:8px"><div style="display:flex;justify-content:space-between"><b>${t.id}</b><span>SOLL ${soll} · IST ${ist}</span></div><small style="color:${p>=100?'#3fe0a5':p>=85?'#ffb84d':'#ff6677'}">${p}% besetzt</small></div>`}).join('');const groups={};abs.forEach(a=>groups[a.type]=(groups[a.type]||0)+1);document.getElementById('reportAbsences').innerHTML=Object.keys(groups).length?Object.entries(groups).map(([k,v])=>`<div class="section-box" style="margin-bottom:8px;display:flex;justify-content:space-between"><b>${k}</b><span>${v} Tag${v===1?'':'e'}</span></div>`).join(''):'<div class="notice">✓ Keine Abwesenheiten im Zeitraum.</div>';const factor=dates.length/7;document.getElementById('reportHours').innerHTML=active.map(e=>{const h=hoursForEmployeeDates(e.id,dates),target=(Number(e.weeklyHours)||0)*factor,d=h-target;return {e,h,target,d}}).sort((a,b)=>b.h-a.h).slice(0,15).map(x=>`<div class="section-box" style="margin-bottom:8px"><div style="display:flex;justify-content:space-between"><b>${x.e.first} ${x.e.last}</b><span>${x.h.toFixed(1)} / ${x.target.toFixed(1)} Std.</span></div><small style="color:${x.d>0?'#ff6677':Math.abs(x.d)<1?'#3fe0a5':'var(--muted)'}">${x.d>=0?'+':''}${x.d.toFixed(1)} Std. Differenz</small></div>`).join('');document.getElementById('reportMix').innerHTML=TYPES.map(t=>`<div class="section-box" style="margin-bottom:8px;display:flex;justify-content:space-between"><b>${t.id}</b><span>${wa.filter(a=>a.type===t.id).length} Schichten</span></div>`).join('');let alerts=[];active.forEach(e=>{const h=hoursForEmployeeDates(e.id,dates),target=(Number(e.weeklyHours)||0)*factor;if(target&&h>target+0.1)alerts.push(`${e.first} ${e.last}: ${(h-target).toFixed(1)} Std. über dem Zeitraum-SOLL`)});wa.forEach(a=>{if(absences.some(x=>x.employeeId===a.employeeId&&x.date===a.date)){const e=employees.find(x=>x.id===a.employeeId);alerts.push(`${e?.first||''} ${e?.last||''}: trotz Abwesenheit am ${new Date(a.date+'T00:00:00').toLocaleDateString('de-DE')} eingeplant`)}});dates.forEach(d=>TYPES.forEach(t=>{const miss=Math.max(0,getSoll(d,t.id)-assignmentsFor(d,t.id).length);if(miss)alerts.push(`${new Date(d+'T00:00:00').toLocaleDateString('de-DE',{weekday:'short',day:'2-digit',month:'2-digit'})} · ${t.id}: ${miss} Position${miss===1?'':'en'} offen`)}));document.getElementById('reportAlertCount').textContent=alerts.length;document.getElementById('reportAlerts').innerHTML=alerts.length?alerts.slice(0,20).map(a=>`<div class="section-box" style="margin-bottom:8px"><span class="status inactive">!</span> ${a}</div>`).join(''):'<div class="notice">✓ Keine Auffälligkeiten im gewählten Zeitraum.</div>'}
'''
needle='function switchView(name){'
if 'function renderReports()' not in s:s=s.replace(needle,fn+needle,1)
oldsw="if(name==='overview'||name==='reports')renderOverview()"
if oldsw in s:s=s.replace(oldsw,"if(name==='overview')renderOverview();if(name==='reports')renderReports()",1)
else:
    raise SystemExit('switchView reports hook not found')
p.write_text(s,encoding='utf-8')
print('Reports Dashboard v2 erfolgreich eingebaut')